/// <summary>
/// createSpotCount's request: an on-demand count of an item and/or a location in a warehouse.
/// The server creates the journal and its lines; the device never inserts journal lines.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountSpotRequest
{
    DataAreaId dataAreaId;
    str        userId;
    str        warehouseId;
    str        itemNumber;
    str        locationId;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('UserId')]
public str parmUserId(str _value = userId)
{
    userId = _value;
    return userId;
}

[DataMemberAttribute('WarehouseId')]
public str parmWarehouseId(str _value = warehouseId)
{
    warehouseId = _value;
    return warehouseId;
}

[DataMemberAttribute('ItemNumber')]
public str parmItemNumber(str _value = itemNumber)
{
    itemNumber = _value;
    return itemNumber;
}

[DataMemberAttribute('LocationId')]
public str parmLocationId(str _value = locationId)
{
    locationId = _value;
    return locationId;
}
